// Extract and transform the top 5 repositories from GitHub Search API
const data = $input.first().json;

if (!data.items || data.items.length === 0) {
  throw new Error('No repositories found in GitHub API response');
}

const top5 = data.items.slice(0, 5).map((repo, index) => ({
  rank: index + 1,
  name: repo.full_name,
  description: repo.description || 'No description provided',
  stars: repo.stargazers_count,
  forks: repo.forks_count,
  language: repo.language || 'Unknown',
  url: repo.html_url,
  owner: repo.owner.login,
  repoName: repo.name,
  openIssues: repo.open_issues_count,
  updatedAt: new Date(repo.updated_at).toLocaleDateString('en-US', {
    year: 'numeric', month: 'short', day: 'numeric'
  }),
  topics: (repo.topics || []).slice(0, 3).join(', ') || 'None'
}));

// Return array of items — n8n will split them for downstream nodes
return top5.map(repo => ({ json: repo }));

// Merge enriched data with our transformed repo data
const enriched = $input.first().json;
const inputData = $('Transform - Filter Top 5 Repos').first().json;

// Build the final enriched object
return [{
  json: {
    rank: inputData.rank,
    name: inputData.name,
    description: inputData.description,
    stars: inputData.stars,
    forks: inputData.forks,
    language: inputData.language,
    url: inputData.url,
    openIssues: inputData.openIssues,
    updatedAt: inputData.updatedAt,
    topics: inputData.topics,
    // Enriched fields from second API call
    watchersCount: enriched.subscribers_count || 0,
    defaultBranch: enriched.default_branch || 'main',
    license: enriched.license ? enriched.license.spdx_id : 'None',
    isArchived: enriched.archived || false,
    hasWiki: enriched.has_wiki || false,
    networkCount: enriched.network_count || 0
  }
}];

// Aggregate ALL items from the IF node (true branch) into a single Discord message
const allItems = $input.all();

const now = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  hour: '2-digit', minute: '2-digit', timeZoneName: 'short'
});

let repoLines = allItems.map(item => {
  const r = item.json;
  return [
    `**#${r.rank} — [${r.name}](${r.url})**`,
    `> ${r.description}`,
    `⭐ **${r.stars.toLocaleString()} stars** | 🍴 ${r.forks.toLocaleString()} forks | 🐛 ${r.openIssues} issues`,
    `🔤 Language: \`${r.language}\` | 📄 License: \`${r.license}\` | 👀 Watchers: ${r.watchersCount}`,
    `🏷 Topics: \`${r.topics}\` | 📅 Updated: ${r.updatedAt}`,
    ''
  ].join('\n');
}).join('\n---\n\n');

const message = {
  embeds: [
    {
      title: '🔥 GitHub JavaScript Trending — Hourly Digest',
      description: `**${now}**\n\nTop repositories with **> 1,000 ⭐** sorted by stars:\n\n${repoLines}`,
      color: 5814783,
      footer: {
        text: 'Powered by n8n · GitHub Search API · Data refreshed every hour'
      }
    }
  ]
};

return [{ json: message }];

// Aggregate all items from false branch (stars <= 1000) into a Discord message
const allItems = $input.all();

const now = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  hour: '2-digit', minute: '2-digit', timeZoneName: 'short'
});

let repoLines = allItems.map(item => {
  const r = item.json;
  return [
    `**#${r.rank} — [${r.name}](${r.url})**`,
    `> ${r.description}`,
    `⭐ ${r.stars.toLocaleString()} stars | 🍴 ${r.forks.toLocaleString()} forks | 🐛 ${r.openIssues} issues`,
    `🔤 Language: \`${r.language}\` | Updated: ${r.updatedAt}`,
    ''
  ].join('\n');
}).join('\n---\n\n');

const message = {
  embeds: [
    {
      title: '📊 GitHub JS Repos — Low Stars Digest',
      description: `**${now}**\n\nRepositories with **≤ 1,000 ⭐** (emerging or niche):\n\n${repoLines}\n\n💡 *These repos have fewer stars but may be worth watching!*`,
      color: 16744272,
      footer: {
        text: 'Powered by n8n · GitHub Search API'
      }
    }
  ]
};

return [{ json: message }];

// Format error alert for Discord
const error = $input.first().json;

const message = {
  embeds: [
    {
      title: '🚨 n8n Workflow Error — GitHub Digest',
      description: [
        `**Error in workflow:** \`${error.workflow?.name || 'GitHub Daily Digest'}\``,
        `**Failed node:** \`${error.node?.name || 'Unknown'}\``,
        `**Error message:** ${error.error?.message || 'Unknown error'}`,
        `**Timestamp:** ${new Date().toISOString()}`,
        '',
        '*The daily digest could not be delivered. Please check n8n logs.*'
      ].join('\n'),
      color: 15548997,
      footer: { text: 'n8n Error Handler' }
    }
  ]
};

return [{ json: message }];
